-- V18: durable payment context, policy decision evidence, and idempotent submissions.\n-- Fail closed if legacy applications cannot be tied to an authoritative invoice/contract.\nALTER TABLE payment_application ADD COLUMN contract_id uuid;\nUPDATE payment_application pa\n   SET contract_id = i.contract_id\n  FROM invoice i\n WHERE i.tenant_id = pa.tenant_id\n   AND i.invoice_id = pa.invoice_id\n   AND pa.contract_id IS NULL;\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM payment_application WHERE contract_id IS NULL) THEN\n    RAISE EXCEPTION 'V18 blocked: payment_application contains rows without a resolvable invoice contract';\n  END IF;\nEND $$;\nALTER TABLE payment_application ALTER COLUMN contract_id SET NOT NULL;\n-- Composite uniqueness lets the database enforce that the application context matches its invoice.\nCREATE UNIQUE INDEX ux_invoice_payment_context\n  ON invoice (tenant_id, invoice_id, project_id, contract_id, subcontractor_id);\nCREATE UNIQUE INDEX ux_contract_project_context\n  ON contract (tenant_id, contract_id, project_id);\nALTER TABLE payment_application\n  ADD CONSTRAINT fk_payment_application_invoice_context\n    FOREIGN KEY (tenant_id, invoice_id, project_id, contract_id, subcontractor_id)\n    REFERENCES invoice (tenant_id, invoice_id, project_id, contract_id, subcontractor_id),\n  ADD CONSTRAINT fk_payment_application_contract_project\n    FOREIGN KEY (tenant_id, contract_id, project_id)\n    REFERENCES contract (tenant_id, contract_id, project_id),\n  ADD CONSTRAINT fk_payment_application_subcontractor\n    FOREIGN KEY (tenant_id, subcontractor_id) REFERENCES party (tenant_id, party_id);\n\nALTER TABLE payment_application\n  ADD COLUMN approval_policy_version varchar(80),\n  ADD COLUMN submission_idempotency_key varchar(200),\n  ADD COLUMN submission_request_hash char(64),\n  ADD COLUMN process_instance_id varchar(64);\nCREATE UNIQUE INDEX ux_payment_application_idempotency\n  ON payment_application (tenant_id, submission_idempotency_key)\n  WHERE submission_idempotency_key IS NOT NULL;\n\nCREATE TABLE payment_approval_decision (\n  tenant_id uuid NOT NULL,\n  approval_id uuid NOT NULL,\n  payment_application_id uuid NOT NULL,\n  project_id uuid NOT NULL,\n  approval_route varchar(30) NOT NULL,\n  decision_source varchar(20) NOT NULL CHECK (decision_source IN ('POLICY','HUMAN')),\n  decision varchar(20) NOT NULL CHECK (decision IN ('APPROVED','REJECTED')),\n  approved_amount numeric(18,2) NOT NULL CHECK (approved_amount > 0),\n  policy_version varchar(80) NOT NULL,\n  decision_reason text NOT NULL CHECK (length(trim(decision_reason)) > 0),\n  decided_by uuid,\n  decided_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, approval_id),\n  FOREIGN KEY (tenant_id, payment_application_id)\n    REFERENCES payment_application (tenant_id, payment_application_id),\n  FOREIGN KEY (tenant_id, project_id) REFERENCES project (tenant_id, project_id)\n);\nALTER TABLE payment_approval_decision ENABLE ROW LEVEL SECURITY;\nALTER TABLE payment_approval_decision FORCE ROW LEVEL SECURITY;\nCREATE POLICY payment_approval_decision_tenant_isolation ON payment_approval_decision\n  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)\n  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);\nGRANT SELECT, INSERT ON payment_approval_decision TO app_user;\nREVOKE UPDATE, DELETE ON payment_approval_decision FROM app_user;